css:
/* Orbit: flight-document lettering, a star field and orbit rings behind the chat. */
[data-chat-header], .chat-markdown :is(h1, h2, h3) { font-family: var(--font-mono, ui-monospace, monospace); }
.chat-markdown :is(h1, h2, h3) { text-transform: uppercase; letter-spacing: 0.08em; }

/* Deep space: three tiled star layers (tile sizes that do not line up), orbit rings and a faint sun. */
.dark [data-workspace-area="conversation"] {
  background-image:
    radial-gradient(1.2px 1.2px at 23px 41px, rgba(255, 255, 255, 0.9), transparent),
    radial-gradient(1px 1px at 151px 97px, rgba(255, 255, 255, 0.7), transparent),
    radial-gradient(1px 1px at 97px 171px, rgba(200, 220, 255, 0.6), transparent),
    radial-gradient(1.5px 1.5px at 211px 263px, rgba(255, 240, 220, 0.9), transparent),
    radial-gradient(1px 1px at 289px 31px, rgba(255, 255, 255, 0.55), transparent),
    radial-gradient(1px 1px at 61px 337px, rgba(255, 255, 255, 0.6), transparent),
    radial-gradient(1.2px 1.2px at 401px 211px, rgba(200, 220, 255, 0.8), transparent),
    radial-gradient(1px 1px at 353px 389px, rgba(255, 255, 255, 0.5), transparent),
    repeating-radial-gradient(circle at 104% 112%, transparent 0 179px, rgba(150, 175, 215, 0.10) 179px 180px),
    radial-gradient(circle at 104% 112%, rgba(255, 138, 61, 0.16), transparent 340px) !important;
  background-size: 211px 211px, 211px 211px, 211px 211px, 433px 433px, 433px 433px, 433px 433px, 457px 457px, 457px 457px, auto, auto !important;
}

/* Flight document: only the orbit rings, in faint ink. */
:root:not(.dark) [data-workspace-area="conversation"] {
  background-image:
    repeating-radial-gradient(circle at 104% 112%, transparent 0 179px, rgba(17, 21, 28, 0.07) 179px 180px),
    radial-gradient(circle at 104% 112%, rgba(194, 65, 12, 0.08), transparent 340px) !important;
}

/* The composer glows like an engine when it has focus. */
.dark [data-slot="composer-host"]:focus-within { box-shadow: 0 0 0 1px rgba(255, 138, 61, 0.45), 0 0 28px rgba(255, 138, 61, 0.18) !important; }
:root:not(.dark) [data-slot="composer-host"]:focus-within { box-shadow: 0 0 0 1px rgba(194, 65, 12, 0.45) !important; }

/* Links and "Working" in ion blue. */
:root:not(.dark) { --info: #1f5f99 !important; --info-foreground: #1f5f99 !important; }
.dark { --info: #7cc4ff !important; --info-foreground: #7cc4ff !important; }
:root:not(.dark) ::selection { background: #fbd6bf; color: #11151c; }
.dark ::selection { background: #5a3418; color: #fff4ea; }
